using System;using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.UI;using DeadQuarantine.PvPvE;using DeadQuarantine.PvPvE.Networking;
public sealed class PvPvENovemberTests {
 PvPvENetworkSettings Settings=>AssetDatabase.LoadAssetAtPath<PvPvENetworkSettings>("Assets/PvPvE/Settings/PvPvENetworkSettings.asset");PvPvELoadoutCatalog Catalog=>Settings.Loadouts;
 [Test] public void ThirdAttachmentRequiresTheCorrectGunfighter(){var c=Catalog.Default(0);c.primary="SemiRifle";c.primaryAttachments=new(){scope="Scope_01",support="Grip_01"};Assert.IsTrue(Catalog.Validate(c,out _));c.primaryAttachments.muzzle="Muzzle_Silencer_01";Assert.IsFalse(Catalog.Validate(c,out _));c.wildcard1="wildcard.secondary_gunfighter";Assert.IsFalse(Catalog.Validate(c,out _));c.wildcard1="wildcard.primary_gunfighter";Assert.IsTrue(Catalog.Validate(c,out var error),error);}
 [Test] public void CategoriesAndBothGreedsValidateAllFourDistinctPerksAndPick10(){var c=Catalog.Default(0);c.perk1=Catalog.perks.Find(PassivePerk.Boots).id;c.perk2=Catalog.perks.Find(PassivePerk.Gloves).id;c.perk1Extra=Catalog.perks.Find(PassivePerk.Kneepads).id;c.perk2Extra=Catalog.perks.Find(PassivePerk.Holster).id;Assert.IsFalse(Catalog.Validate(c,out _));c.wildcard1="wildcard.greed";c.wildcard2="wildcard.handling_greed";Assert.IsTrue(Catalog.Validate(c,out var error),error);Assert.AreEqual(10,Catalog.Pick10Cost(c));Assert.IsTrue(Catalog.TryPerkMask(c,out var mask));Assert.AreEqual(4,Convert.ToString(mask,2).Count(v=>v=='1'));c.perk1Extra=c.perk1;Assert.IsFalse(Catalog.Validate(c,out _));c.perk1Extra="";c.perk1=Catalog.perks.Find(PassivePerk.Gloves).id;Assert.IsFalse(Catalog.Validate(c,out _));}
 [Test] public void EnergyDrinkBelongsToMobilityWithoutChangingOriginalPerkData(){var perk=Catalog.perks.Find(PassivePerk.Canteen);Assert.AreEqual(PerkCategory.Mobility,perk.CategoryForPvPvE);}
 [Test] public void FiveClassesPersistTheirNewSlots(){string profile="november-qa-"+Guid.NewGuid();try{var store=new PvPvEClassStore(Catalog,profile);for(int i=0;i<5;i++){var c=Catalog.Default(i);c.wildcard1="wildcard.greed";c.perk1=Catalog.perks.Find(PassivePerk.Boots).id;c.perk1Extra=Catalog.perks.Find(PassivePerk.Canteen).id;Assert.IsTrue(store.Save(i,c,out var error),error);}var reloaded=new PvPvEClassStore(Catalog,profile);for(int i=0;i<5;i++){Assert.AreEqual(store.Get(i).perk1Extra,reloaded.Get(i).perk1Extra);Assert.IsTrue(Catalog.Validate(reloaded.Get(i),out _));}}finally{PlayerPrefs.DeleteKey("DQ.PvPvE.Classes.v1."+profile);PlayerPrefs.DeleteKey("DQ.PvPvE.Classes.v1."+profile+".backup");}}
 [TestCase(false,false,false,100)] [TestCase(false,true,false,150)] [TestCase(false,false,true,125)] [TestCase(false,true,true,175)] [TestCase(true,false,false,10)] [TestCase(true,true,false,15)] [TestCase(true,false,true,12)] [TestCase(true,true,true,17)] public void AuthoritativeBonusesUseTheBaseAndZombieLongshotIsTwentyPercent(bool zombie,bool head,bool far,double expected){Assert.AreEqual(expected,Settings.EliminationAward(zombie,head,far).Total);}
 [Test] public void RifleServerFillUsesItsOwnAmmunitionEvents(){var rifle=Catalog.Find("Rifle");Assert.That(rifle.reloadFillSeconds,Is.InRange(1.49f,1.52f));Assert.That(rifle.emptyReloadFillSeconds,Is.InRange(1.46f,1.49f));}
 [Test] public void EditorMissingComponentsAreAddedUsingUnityNullSemantics(){var go=new GameObject("Button",typeof(RectTransform),typeof(Image),typeof(Button));try{PvPvEUIFactory.StyleButton(go.GetComponent<Button>());Assert.IsNotNull(go.GetComponent<Outline>());}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test] public void FractionalCustomScoresAreNotSilentlyRounded(){var settings=UnityEngine.Object.Instantiate(Settings);try{settings.KillScore=101;Assert.AreEqual(176.75,settings.EliminationAward(false,true,true).Total);}finally{UnityEngine.Object.DestroyImmediate(settings);}}
 [Test] public void ZombieCapAndDistributionRemainConfigured(){Assert.AreEqual(10,Settings.MaxZombiesAlive);Assert.AreEqual(80,Settings.WalkerChance);Assert.AreEqual(15,Settings.RunnerChance);Assert.AreEqual(5,Settings.DogChance);}
}
